def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)  # tolerate both shapes
    outcome = result.get("outcome") or result.get("decision")
    limit = result.get("credit_limit") or result.get("limit") or 0

    # Network referral rule: self_employed with requested_limit above 6000
    # must go to manual review unless it is a decline.
    if app.get("employment") == "self_employed" and int(app.get("requested_limit", 0)) > 6000:
        if outcome in ("declined", "decline"):
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if outcome in ("approved", "approve"):
        return {"action": "issue", "limit": int(limit or 0)}
    if outcome in ("declined", "decline"):
        return {"action": "decline", "limit": 0}
    # manual_review / refer
    return {"action": "queue_review", "limit": 0}
